<style>
.teacher-page{--navy:#102f50;--muted:#596a7b;--line:#dce5ed;color:var(--navy);background:#f5f8fb;min-height:100vh}.teacher-page a:focus-visible{outline:3px solid #2389b8;outline-offset:4px}
.teacher-topbar{background:#fff;border-bottom:1px solid var(--line)}.teacher-topbar>div{max-width:1120px;margin:auto;padding:20px 24px;display:flex;align-items:center;justify-content:space-between;gap:16px}.teacher-brand{font-size:18px;font-weight:750;color:var(--navy);text-decoration:none}.teacher-topbar .text-link{font-size:14px}
.teacher-shell{max-width:1120px;margin:auto;padding:24px 24px 60px}.teacher-crumbs{display:flex;flex-wrap:wrap;gap:9px;font-size:12px;color:var(--muted);margin-bottom:24px}.teacher-crumbs a{color:var(--muted)}
.teacher-hero{background:var(--navy);color:#fff;border-radius:20px;padding:36px;display:flex;align-items:flex-start;gap:24px;overflow-wrap:anywhere}.teacher-hero .avatar{width:96px;height:96px;flex-shrink:0;border-radius:20px;font-size:32px;background:#e5f4f7}.teacher-hero .avatar img{width:96px;height:96px}
.teacher-kicker{font-size:11px;text-transform:uppercase;letter-spacing:1.6px;font-weight:650;margin:0 0 10px;color:#a8d7e5}.teacher-hero h1{font-size:32px;line-height:1.2;margin:0 0 12px}.teacher-hero h1 a{color:#fff;text-decoration:none}.teacher-hero h1 a:hover{text-decoration:underline}.teacher-subtitle{font-size:16px;line-height:1.6;color:#e0edf5;margin:0 0 8px}.teacher-location{font-size:14px;color:#b8cad9;margin:0}
.teacher-columns{display:grid;grid-template-columns:minmax(0,1fr) 300px;align-items:start;gap:24px;margin-top:24px}.teacher-panel{background:#fff;border:1px solid var(--line);border-radius:16px;padding:28px;margin-bottom:20px;overflow-wrap:anywhere}.teacher-panel h2{font-size:19px;margin:0 0 16px}.teacher-panel p{line-height:1.7}.teacher-panel .bio{margin:0;white-space:pre-line}.teacher-panel .tag{background:#edf5f8;color:#1f5770;padding:8px 13px;border-radius:8px}.teacher-panel .tags{margin:0}.teacher-panel .mode-heading{margin-top:26px}
.teacher-stats{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:22px;padding-top:20px;border-top:1px solid var(--line)}.teacher-stat strong{font-size:20px;display:block}.teacher-stat span{font-size:12px;color:var(--muted)}
.teacher-message{position:sticky;top:24px}.teacher-message .teacher-kicker{color:#476b80}.teacher-message .btn{display:block;text-align:center;background:var(--navy);line-height:1.5}.teacher-message .teacher-price{font-size:27px;font-weight:700;margin:10px 0}.teacher-message .meta{line-height:1.6;margin:12px 0;color:var(--muted)}.teacher-message .teacher-secondary{background:#fff;color:var(--navy);border:1px solid var(--line);margin-top:10px}.teacher-trial{background:#edf7f3;color:#246346;border-radius:8px;padding:9px 12px;font-size:13px;margin-bottom:18px}
.teacher-review{padding:16px 0;border-bottom:1px solid var(--line)}.teacher-review:first-of-type{padding-top:0}.teacher-review p{margin:8px 0 0}.teacher-review .meta{color:var(--muted)}.teacher-review-stars{color:#976609;font-weight:650}.teacher-pagination{display:flex;justify-content:space-between;gap:16px;margin-top:20px}.teacher-note{font-size:13px;color:var(--muted);line-height:1.7}.teacher-bottom{margin-top:12px;padding:18px 0;border-top:1px solid var(--line);font-size:13px;color:var(--muted)}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.directory-page{--ink:#211e1a;--muted:#777067;--line:#eee7df;--red:#c91f18;--gold:#ffc02e;background:#fffaf4;color:var(--ink)}.directory-page .teacher-topbar{background:#fffaf4;border-color:#eee7df}.directory-topbar>div{max-width:1100px;display:grid;grid-template-columns:1fr auto auto auto;gap:22px;padding:14px 22px}.directory-page .teacher-brand{color:var(--ink);font-size:16px}.directory-page .teacher-brand small{display:block;font-size:10px;font-weight:500;color:var(--muted)}.directory-topbar nav{display:flex;align-items:center;gap:16px}.directory-topbar nav a{font-size:12px;color:#554f47;text-decoration:none;font-weight:650}.directory-language select{max-width:125px;border:1px solid var(--line);border-radius:10px;background:#fff;padding:9px 12px;color:var(--ink)}.directory-app-link{display:inline-flex;align-items:center;justify-content:center;padding:10px 16px;border-radius:10px;background:var(--red);color:#fff;text-decoration:none;font-size:12px;font-weight:750}.directory-shell{max-width:760px;margin:0 auto;padding:12px 20px 56px}.directory-page .teacher-crumbs{margin:0 0 14px;color:#776f65;font-size:12px}.directory-page .teacher-crumbs a{color:#776f65;text-decoration:none}.directory-heading h1{font-size:28px;line-height:1.15;letter-spacing:-.5px;color:var(--ink);margin:10px 0 6px}.directory-heading p{font-size:14px;color:#615b53;line-height:1.5;margin:0 0 16px}.directory-search{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:14px}.directory-search input[type=search]{flex:1 1 100%;min-width:180px;border:1px solid #e8dfd5;border-radius:11px;padding:12px 14px;background:#fff;font-size:14px}.directory-search select{border:1px solid #e8dfd5;border-radius:999px;padding:10px 12px;background:#fff;color:#39342e}.directory-trial{display:flex;align-items:center;gap:6px;border:1px solid #e8dfd5;border-radius:999px;padding:9px 12px;background:#fff;font-size:12px}.directory-search button{border:0;border-radius:999px;background:var(--ink);color:#fff;padding:10px 15px;font-weight:700}.directory-clear{color:var(--muted);font-size:12px}.directory-browse{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.directory-browse a{color:#4b443d;background:#fff;border:1px solid var(--line);border-radius:999px;padding:8px 12px;font-size:12px;text-decoration:none}.directory-results{display:grid;gap:10px;margin-top:12px}.directory-card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:18px 16px;box-shadow:0 4px 16px #38210c08}.directory-card-heading{display:flex;align-items:center;gap:12px}.directory-avatar{width:48px;height:48px;display:grid;place-items:center;flex:0 0 48px;border-radius:50%;background:#fde4e1;color:#a8221d;font-size:16px;font-weight:750;overflow:hidden}.directory-avatar img{width:48px;height:48px;object-fit:cover}.directory-card h2{margin:0 0 5px;font-size:17px}.directory-card h2 a{color:var(--ink);text-decoration:none}.directory-points{display:inline-block;background:#fff0c4;color:#72551b;border-radius:5px;padding:3px 6px;font-size:10px;font-weight:700}.directory-place{font-size:12px;color:#766f66;margin:12px 0 8px}.directory-subjects{font-size:13px;font-weight:600;margin:0 0 9px}.directory-tags{display:flex;gap:6px;flex-wrap:wrap}.directory-tags span{padding:5px 8px;border-radius:7px;background:#f3eee8;color:#5d5144;font-size:10px}.directory-rate{font-size:12px;color:#605950;margin:10px 0}.directory-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:12px}.directory-actions a{text-align:center;border-radius:10px;padding:10px 8px;text-decoration:none;font-size:12px;font-weight:700}.directory-contact{background:var(--red);color:#fff}.directory-profile{border:1px solid #e6ddd3;color:#332e28}.directory-empty{padding:22px;border:1px solid var(--line);border-radius:14px;color:var(--muted);background:#fff}.directory-pagination{display:flex;justify-content:space-between;margin-top:18px}.directory-pagination a{border:1px solid var(--line);border-radius:10px;padding:10px 14px;background:#fff;color:var(--ink);text-decoration:none}
@media(max-width:760px){.teacher-columns{grid-template-columns:1fr}.teacher-message{position:static;grid-row:1}.teacher-shell{padding:18px 16px 36px}.teacher-hero{padding:24px;gap:18px}.teacher-hero h1{font-size:25px}.teacher-hero .avatar{width:68px;height:68px;border-radius:14px;font-size:25px}.teacher-hero .avatar img{width:68px;height:68px}.teacher-panel{padding:22px}.teacher-topbar>div{padding:18px 16px}}
@media(max-width:760px){.directory-topbar>div{grid-template-columns:1fr auto;gap:10px;padding:10px 14px}.directory-topbar nav{grid-column:1/-1;grid-row:2;justify-content:space-between;gap:8px}.directory-topbar nav a{font-size:11px}.directory-language{grid-column:2;grid-row:1}.directory-app-link{display:none}.directory-shell{padding:10px 16px 34px}.directory-heading h1{font-size:24px}.directory-search input[type=search]{font-size:13px}.directory-card{padding:15px}.directory-actions{grid-template-columns:1fr}}
@media(max-width:420px){.teacher-hero{flex-direction:column}.teacher-topbar .text-link{font-size:12px}.teacher-subtitle{font-size:14px}}
.directory-page .teacher-hero{background:#fffaf4;color:var(--ink);border:1px solid var(--line);border-radius:18px;box-shadow:0 4px 16px #38210c08}.directory-page .teacher-hero .avatar{background:#fde4e1;color:#a8221d}.directory-page .teacher-kicker{color:#a8221d}.directory-page .teacher-hero h1{color:var(--ink)}.directory-page .teacher-subtitle,.directory-page .teacher-location,.directory-page .teacher-note{color:#6f675e}.directory-page .teacher-shell{max-width:1000px}.directory-page .teacher-panel{border-color:var(--line);border-radius:18px;box-shadow:0 4px 16px #38210c08}.directory-page .teacher-panel .tag{background:#f3eee8;color:#5d5144}.directory-page .teacher-panel .text-link{color:var(--ink)}.directory-page .teacher-panel .text-link:hover{color:var(--red)}.directory-page .teacher-message .btn{background:var(--red);border-radius:10px;font-weight:750}.directory-page .teacher-trial{background:#fff0c4;color:#72551b}.directory-page .teacher-stat strong{color:var(--ink)}.directory-hub-card{display:flex;justify-content:space-between;gap:14px;color:var(--ink);text-decoration:none}.directory-hub-card:hover{border-color:#d4bca6}
</style>
